    const p = pages.find(p => p.thumbnail && phMatch(p.title, name));
    if (p) { const o = p.original || {}; return { t: p.thumbnail.source, o: o.source || "", w: o.width || 0, x: p.extract || "", u: p.fullurl || "" }; }
